document.addEventListener("DOMContentLoaded",(()=>{SnapSelect(".snapSelect",{liveSearch:!0,placeholder:"Select Post Types...",clearAllButton:!0,closeOnSelect:!1,allowEmpty:!0});let e=document.getElementById("cfo-purge-container").children;for(const o of e)o.onclick=function(){confirm("Are you sure you want to clear the cache for "+o.children[0].innerHTML)&&t(o.dataset.cfoMarket)};async function t(e){try{const t=document.getElementById("cfo-purge-result");t.innerHTML="",t.classList.add("cfo-loading");const o=await fetch("/wp-json/cfo/purge_market?"+new URLSearchParams({market_id:e}).toString(),{headers:{"X-WP-Nonce":myUserData.nonce},credentials:"same-origin"});if(!o.ok)throw t.classList.remove("cfo-loading"),new Error(`Response status: ${o.status}`);const n=await o.json();let c="Nothing to display.";try{let e=JSON.parse(n);c=1==e.success?"Successfully purged.":JSON.stringify(e.errors)}catch(e){c=n}t.classList.remove("cfo-loading"),t.innerHTML=c}catch(e){console.error(e)}}}));